from collections import deque

def comps(g):
 H,W=len(g),len(g[0]); seen=set(); out=[]
 for r in range(H):
  for c in range(W):
   if g[r][c]==7 or (r,c) in seen: continue
   q=[(r,c)]; seen.add((r,c)); pts=[]
   while q:
    x,y=q.pop(); pts.append((x,y))
    for nx,ny in ((x+1,y),(x-1,y),(x,y+1),(x,y-1)):
     if 0<=nx<H and 0<=ny<W and g[nx][ny]!=7 and (nx,ny) not in seen:
      seen.add((nx,ny)); q.append((nx,ny))
   vals=sorted(set(g[x][y] for x,y in pts)-{0})
   out.append((pts, vals))
 return out
